+
+async function schedulerJobProcessor(deps: WorkerDeps, job: Job<ScheduleJobData>): Promise<void> {
+  const { prisma } = deps;
+  const post = await prisma.post.findUnique({
+    where: { id: job.data.postId },
+    include: { variants: { include: { channel: true } } },
+  });
