+  const ready = post.variants
+    .filter((v) => v.publishState !== "PUBLISHED" && v.content.trim().length > 0)
+    .map((v) => v.id);
+  if (ready.length === 0) return;
+  await createPublisher(deps).enqueuePublish(post.id, job.data.workspaceId, ready);
+}
+
+async function reconcilerJobProcessor(deps: WorkerDeps): Promise<void> {
+  await runScheduleReconciler(deps);
+}
+
+/**
+ * 5-min cron safety net (spec §5): picks up SCHEDULED posts whose time has
+ * come — covers >7d schedules and any delayed job that never fired.
+ */
+export async function runScheduleReconciler(deps: QueueDeps): Promise<number> {
+  const now = new Date();
+  const overdue = await deps.prisma.post.findMany({
+    where: { status: "SCHEDULED", scheduledAt: { lte: now } },
+    include: { variants: { include: { channel: true } } },
+  });
+  for (const post of overdue) {
+    const ready = post.variants
+      .filter((v) => v.publishState !== "PUBLISHED" && v.content.trim().length > 0)
+      .map((v) => v.id);
+    if (ready.length > 0) {
+      await createPublisher(deps).enqueuePublish(post.id, post.workspaceId, ready);
+    }
+  }
+  return overdue.length;
+}
